"""Class 3 Mathematics Chapter 4: Vacation with My Nani Maa - Complete Interactive Simulators."""

simulators = {'sim_hidden_marble_trick': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-amber-400">Interactive Lab 1</span>\n            <h3 class="text-lg font-bold text-slate-100">Handkerchief Marble Hide-and-Seek</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-amber-500/20 text-amber-300 font-semibold border border-amber-500/30">Total - Visible = Hidden</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Observe the wooden tabletop. A total of <strong id="marbleTotalDisp">15</strong> marbles were placed here. Some marbles are hidden beneath the cloth, while others remain visible in the open!\n    </p>\n\n    <!-- Tabletop Stage -->\n    <div class="bg-amber-950/20 border border-amber-800/40 rounded-xl p-4 min-h-[170px] relative overflow-hidden flex flex-col justify-between">\n        <div class="flex justify-between items-center text-xs text-amber-300 mb-2 border-b border-amber-800/30 pb-1">\n            <span>Wooden Tabletop Stage</span>\n            <span class="font-mono font-bold" id="marbleVisibleCountBadge">Visible: 9 | Hidden: 6</span>\n        </div>\n\n        <div class="grid grid-cols-1 sm:grid-cols-2 gap-4 items-center">\n            <!-- Open Visible Marbles Area -->\n            <div class="bg-slate-900/80 border border-slate-800 rounded-xl p-3 flex flex-col items-center">\n                <span class="text-[11px] font-bold text-slate-400 uppercase tracking-wide mb-2">Visible Marbles</span>\n                <div id="visibleMarblesContainer" class="flex flex-wrap gap-2 justify-center min-h-[48px] py-1">\n                    <!-- Dynamic marble spheres -->\n                </div>\n                <span id="visibleMarblesCountTxt" class="text-xs font-mono text-emerald-400 font-bold mt-1">9 Visible</span>\n            </div>\n\n            <!-- Cloth / Handkerchief Covered Area -->\n            <div class="bg-rose-950/40 border border-rose-700/50 rounded-xl p-3 flex flex-col items-center relative">\n                <div class="flex justify-between items-center w-full mb-1">\n                    <span class="text-[11px] font-bold text-rose-300 uppercase tracking-wide">Under Handkerchief</span>\n                    <button onclick="toggleCloth()" id="clothToggleBtn" class="text-[10px] px-2 py-0.5 rounded bg-rose-800 hover:bg-rose-700 text-white font-semibold">Peeking: Off</button>\n                </div>\n                <div id="clothCover" class="w-full h-14 bg-gradient-to-r from-rose-700 to-pink-800 rounded-lg flex items-center justify-center border-2 border-rose-400/60 shadow-inner transition-all duration-300">\n                    <span id="clothCoverLabel" class="text-xs font-bold text-white tracking-wider">❓ Hidden Under Cloth</span>\n                </div>\n                <div id="hiddenMarblesContainer" class="hidden flex flex-wrap gap-2 justify-center min-h-[48px] py-1 mt-1">\n                    <!-- Revealed marbles when peeked -->\n                </div>\n                <span id="hiddenMarblesCountTxt" class="text-xs font-mono text-amber-300 font-bold mt-1">6 Hidden (15 - 9 = 6)</span>\n            </div>\n        </div>\n\n        <div id="marbleEquationSummary" class="mt-3 p-2.5 rounded-lg bg-slate-900 border border-slate-800 text-center text-xs font-mono text-amber-200">\n            Total 15 - Visible 9 = <strong>6 Hidden Marbles</strong> (Verified by 9 + 6 = 15)\n        </div>\n    </div>\n\n    <!-- Preset Selection Controls -->\n    <div class="flex flex-wrap gap-2 justify-center text-xs">\n        <span class="text-slate-400 self-center">Try Total:</span>\n        <button onclick="setMarblePreset(15, 9)" class="px-2.5 py-1.5 bg-amber-600 text-white rounded font-bold font-mono">15 (9 vis)</button>\n        <button onclick="setMarblePreset(17, 11)" class="px-2.5 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">17 (11 vis)</button>\n        <button onclick="setMarblePreset(20, 13)" class="px-2.5 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">20 (13 vis)</button>\n        <button onclick="setMarblePreset(23, 15)" class="px-2.5 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">23 (15 vis)</button>\n        <button onclick="setMarblePreset(27, 18)" class="px-2.5 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">27 (18 vis)</button>\n    </div>\n</div>\n', 'sim_balushahi_sweet_counts': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-orange-400">Interactive Lab 2</span>\n            <h3 class="text-lg font-bold text-slate-100">Balushahi Serving Platter</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-orange-500/20 text-orange-300 font-semibold border border-orange-500/30">Addition & Consumption</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Combine fresh balushahi sweets from two boxes ($7 + 5 = 12$), then simulate afternoon teatime by eating some to see the remaining quantity!\n    </p>\n\n    <!-- Platter Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-4 text-center">\n        <div class="flex justify-between items-center mb-3">\n            <span class="text-xs text-slate-400 font-semibold">Active Serving Platter</span>\n            <span id="balushahiCountBadge" class="text-base font-black font-mono text-amber-400">12 Sweets on Platter</span>\n        </div>\n\n        <!-- Sweet Platter Display -->\n        <div id="balushahiPlatter" class="min-h-[100px] bg-amber-950/30 border-2 border-amber-600/40 rounded-2xl p-3 flex flex-wrap gap-2.5 items-center justify-center">\n            <!-- Dynamic sweet icons -->\n        </div>\n\n        <!-- Operation Readout -->\n        <div class="mt-3 p-3 bg-slate-900 rounded-lg border border-slate-800">\n            <div id="balushahiEquation" class="text-xl font-black font-mono text-amber-300">\n                Box A (7) + Box B (5) = 12 Sweets\n            </div>\n            <div id="balushahiStatusTxt" class="text-xs text-slate-400 mt-1">\n                Click "Eat 1 Sweet" to observe subtraction in action!\n            </div>\n        </div>\n    </div>\n\n    <!-- Interactive Buttons -->\n    <div class="grid grid-cols-2 sm:grid-cols-4 gap-2 pt-1">\n        <button onclick="addSweet()" class="px-3 py-2 bg-emerald-700 hover:bg-emerald-600 rounded-lg text-xs font-bold text-white shadow">\n            ➕ Add 1 Sweet\n        </button>\n        <button onclick="eatSweet()" class="px-3 py-2 bg-amber-700 hover:bg-amber-600 rounded-lg text-xs font-bold text-white shadow">\n            🍪 Eat 1 Sweet\n        </button>\n        <button onclick="eatMultipleSweets(4)" class="px-3 py-2 bg-rose-800 hover:bg-rose-700 rounded-lg text-xs font-bold text-white shadow">\n            Teatime (-4 Sweets)\n        </button>\n        <button onclick="resetSweets()" class="px-3 py-2 bg-slate-800 hover:bg-slate-700 rounded-lg text-xs font-semibold text-slate-300">\n            Reset (7 + 5 = 12)\n        </button>\n    </div>\n</div>\n', 'sim_story_books_total': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-indigo-400">Interactive Lab 3</span>\n            <h3 class="text-lg font-bold text-slate-100">Ten-Frame Book Bridging</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-indigo-500/20 text-indigo-300 font-semibold border border-indigo-500/30">9 + 7 = 10 + 6 = 16</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Combine <strong>9 storybooks</strong> and <strong>7 puzzle books</strong> using two ten-frames. Click the button to move 1 book into the ten-frame to make a friendly ten!\n    </p>\n\n    <!-- Ten-Frames Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-4">\n        <div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n            <!-- Ten-Frame 1 (Storybooks) -->\n            <div class="bg-slate-900 p-3 rounded-xl border border-indigo-700/50 flex flex-col items-center">\n                <div class="flex justify-between items-center w-full mb-2">\n                    <span class="text-xs font-bold text-indigo-300">Ten-Frame 1: Storybooks</span>\n                    <span id="frame1CountBadge" class="text-xs font-mono font-bold text-indigo-400">9 Books</span>\n                </div>\n                <!-- 2x5 Grid -->\n                <div id="tenFrame1" class="grid grid-cols-5 gap-1.5 p-2 bg-slate-950 rounded-lg border border-slate-800 w-full max-w-xs">\n                    <!-- 10 cells generated dynamically -->\n                </div>\n            </div>\n\n            <!-- Ten-Frame 2 (Puzzle Books) -->\n            <div class="bg-slate-900 p-3 rounded-xl border border-emerald-700/50 flex flex-col items-center">\n                <div class="flex justify-between items-center w-full mb-2">\n                    <span class="text-xs font-bold text-emerald-300">Ten-Frame 2: Puzzle Books</span>\n                    <span id="frame2CountBadge" class="text-xs font-mono font-bold text-emerald-400">7 Books</span>\n                </div>\n                <!-- 2x5 Grid -->\n                <div id="tenFrame2" class="grid grid-cols-5 gap-1.5 p-2 bg-slate-950 rounded-lg border border-slate-800 w-full max-w-xs">\n                    <!-- 10 cells generated dynamically -->\n                </div>\n            </div>\n        </div>\n\n        <!-- Strategy Outcome Equation -->\n        <div class="mt-4 p-3 bg-slate-900 rounded-lg border border-slate-800 text-center">\n            <div id="bookTenFrameEquation" class="text-xl sm:text-2xl font-black font-mono text-indigo-300">\n                9 + 7 = 16 Books\n            </div>\n            <div id="bookTenFrameStepTxt" class="text-xs text-slate-300 mt-1">\n                Initial state: 9 storybooks need 1 more to complete a full decade.\n            </div>\n        </div>\n    </div>\n\n    <!-- Bridging Controls -->\n    <div class="flex flex-wrap gap-2 justify-center">\n        <button onclick="executeMakeTen()" id="btnMakeTen" class="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg text-xs font-bold shadow transition">\n            ✨ Move 1 Book to Make 10\n        </button>\n        <button onclick="resetTenFrames()" class="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-lg text-xs font-semibold">\n            Reset (9 + 7)\n        </button>\n        <button onclick="setBookCustom(8, 5)" class="px-3 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-lg text-xs font-mono">\n            Try 8 + 5\n        </button>\n    </div>\n</div>\n', 'sim_card_equation_triplets': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-pink-400">Interactive Lab 4</span>\n            <h3 class="text-lg font-bold text-slate-100">Fact Family Triplet Cards</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-pink-500/20 text-pink-300 font-semibold border border-pink-500/30">4 Equations in 1 Triplet</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Three number cards form an inseparable fact family. Explore the four related addition and subtraction equations unlocked by these numbers!\n    </p>\n\n    <!-- Triplet Cards Display -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-4 flex flex-col items-center">\n        <!-- 3 Cards Visual -->\n        <div class="flex items-center justify-center gap-3 sm:gap-6 my-2">\n            <div class="w-16 h-24 sm:w-20 sm:h-28 rounded-xl bg-pink-950/60 border-2 border-pink-500 flex flex-col items-center justify-center shadow-lg">\n                <span class="text-[10px] text-pink-300 font-bold">PART</span>\n                <span id="tripletCardA" class="text-3xl sm:text-4xl font-black font-mono text-white">7</span>\n            </div>\n            <span class="text-2xl font-bold text-slate-500">+</span>\n            <div class="w-16 h-24 sm:w-20 sm:h-28 rounded-xl bg-purple-950/60 border-2 border-purple-500 flex flex-col items-center justify-center shadow-lg">\n                <span class="text-[10px] text-purple-300 font-bold">PART</span>\n                <span id="tripletCardB" class="text-3xl sm:text-4xl font-black font-mono text-white">8</span>\n            </div>\n            <span class="text-2xl font-bold text-slate-500">=</span>\n            <div class="w-16 h-24 sm:w-20 sm:h-28 rounded-xl bg-amber-950/60 border-2 border-amber-500 flex flex-col items-center justify-center shadow-lg">\n                <span class="text-[10px] text-amber-300 font-bold">TOTAL</span>\n                <span id="tripletCardTotal" class="text-3xl sm:text-4xl font-black font-mono text-amber-300">15</span>\n            </div>\n        </div>\n\n        <!-- 4 Equations Matrix -->\n        <div class="grid grid-cols-2 gap-2 w-full max-w-md mt-3 text-xs font-mono">\n            <div id="eqBox1" class="bg-slate-900 p-2.5 rounded-lg border border-slate-800 text-center font-bold text-emerald-300">\n                7 + 8 = 15\n            </div>\n            <div id="eqBox2" class="bg-slate-900 p-2.5 rounded-lg border border-slate-800 text-center font-bold text-emerald-300">\n                8 + 7 = 15\n            </div>\n            <div id="eqBox3" class="bg-slate-900 p-2.5 rounded-lg border border-slate-800 text-center font-bold text-amber-300">\n                15 - 7 = 8\n            </div>\n            <div id="eqBox4" class="bg-slate-900 p-2.5 rounded-lg border border-slate-800 text-center font-bold text-amber-300">\n                15 - 8 = 7\n            </div>\n        </div>\n    </div>\n\n    <!-- Presets -->\n    <div class="flex flex-wrap gap-2 justify-center text-xs">\n        <button onclick="setTripletPreset(7, 8, 15)" class="px-3 py-1.5 bg-pink-700 text-white rounded font-mono font-bold">Triplet {7, 8, 15}</button>\n        <button onclick="setTripletPreset(6, 8, 14)" class="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">Triplet {6, 8, 14}</button>\n        <button onclick="setTripletPreset(9, 7, 16)" class="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">Triplet {9, 7, 16}</button>\n        <button onclick="setTripletPreset(5, 9, 14)" class="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">Triplet {5, 9, 14}</button>\n    </div>\n</div>\n', 'sim_bead_string_strategies': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-teal-400">Interactive Lab 5</span>\n            <h3 class="text-lg font-bold text-slate-100">Ginladi Bead String Addition</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-teal-500/20 text-teal-300 font-semibold border border-teal-500/30">Three Paths to 15 + 7</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Solve <strong>15 + 7 = 22</strong> along a 100-bead string using three distinct mental pathways: single units, friendly bridging, or compensation leap!\n    </p>\n\n    <!-- Strategy Selector Tabs -->\n    <div class="grid grid-cols-3 gap-1.5 border-b border-slate-800 pb-2 text-xs">\n        <button onclick="setBeadStrategy(\'bridge\')" id="tabStratBridge" class="px-2 py-1.5 rounded-lg font-bold bg-teal-600 text-white">🌉 Friendly Bridge (+5, +2)</button>\n        <button onclick="setBeadStrategy(\'comp\')" id="tabStratComp" class="px-2 py-1.5 rounded-lg font-semibold bg-slate-800 text-slate-300 hover:bg-slate-700">⚡ Compensation (+10, -3)</button>\n        <button onclick="setBeadStrategy(\'ones\')" id="tabStratOnes" class="px-2 py-1.5 rounded-lg font-semibold bg-slate-800 text-slate-300 hover:bg-slate-700">🐢 Step by Ones (+1 × 7)</button>\n    </div>\n\n    <!-- Ginladi Display -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-4 flex flex-col items-center">\n        <!-- Bead Track -->\n        <div id="ginladiStrategyTrack" class="flex flex-wrap gap-1 justify-center max-w-lg p-2.5 bg-slate-900 rounded-lg border border-slate-800 select-none">\n            <!-- 30 beads displayed for focus -->\n        </div>\n\n        <!-- Strategy Visual Explanation Box -->\n        <div id="beadStrategyExplanation" class="mt-3 p-3 rounded-lg bg-teal-950/40 border border-teal-800/40 text-center w-full max-w-md">\n            <div class="text-lg font-bold font-mono text-teal-300">15 + 5 = 20, then 20 + 2 = 22</div>\n            <div class="text-xs text-slate-300 mt-1">Jump 5 beads to hit clean decade 20, then jump remaining 2 to reach 22!</div>\n        </div>\n    </div>\n</div>\n', 'sim_adding_larger_bundles': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-cyan-400">Interactive Lab 6</span>\n            <h3 class="text-lg font-bold text-slate-100">Stamp Album Decade Leaps</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-cyan-500/20 text-cyan-300 font-semibold border border-cyan-500/30">22 + 30 = 52</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        You have <strong>22 stamps</strong> in an album. A gift packet adds <strong>30 stamps</strong> (3 full tens). Watch how decade additions modify only the tens place!\n    </p>\n\n    <!-- Visual Album Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-4">\n        <div class="grid grid-cols-1 sm:grid-cols-2 gap-4 items-center">\n            <!-- Tens Bundles Visual -->\n            <div class="bg-slate-900 p-3 rounded-xl border border-slate-800 flex flex-col items-center">\n                <span class="text-xs font-bold text-cyan-300 mb-2">Stamp Tens Bundles</span>\n                <div id="stampBundlesDisplay" class="flex flex-wrap gap-2 justify-center my-1">\n                    <!-- Dynamic bundles -->\n                </div>\n                <span id="stampBundlesTotalTxt" class="text-xs font-mono text-slate-300 mt-2">5 Tens Bundles (50) + 2 Loose = 52</span>\n            </div>\n\n            <!-- Number Line Decade Step Display -->\n            <div class="bg-slate-900 p-3 rounded-xl border border-slate-800 flex flex-col items-center">\n                <span class="text-xs font-bold text-cyan-300 mb-2">Number Line Leaps of 10</span>\n                <div class="w-full py-2 flex items-center justify-center font-mono text-xs">\n                    <span class="px-2 py-1 rounded bg-slate-800 text-slate-300">22</span>\n                    <span class="text-cyan-400 font-bold mx-1">➜ (+10) ➜</span>\n                    <span class="px-2 py-1 rounded bg-slate-800 text-slate-300">32</span>\n                    <span class="text-cyan-400 font-bold mx-1">➜ (+10) ➜</span>\n                    <span class="px-2 py-1 rounded bg-slate-800 text-slate-300">42</span>\n                    <span class="text-cyan-400 font-bold mx-1">➜ (+10) ➜</span>\n                    <span class="px-2 py-1 rounded bg-cyan-600 text-white font-bold">52</span>\n                </div>\n                <div class="text-[11px] text-slate-400 mt-2 text-center">Three clean forward hops of 10!</div>\n            </div>\n        </div>\n\n        <div id="stampAddingEquation" class="mt-3 p-2.5 rounded bg-cyan-950/40 border border-cyan-800/40 text-center font-mono font-bold text-cyan-300 text-base">\n            22 + 30 = 52 Stamps\n        </div>\n    </div>\n\n    <!-- Quick Jump Controls -->\n    <div class="flex flex-wrap gap-2 justify-center text-xs">\n        <button onclick="setStampAddition(22, 10)" class="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">Add +10 (32)</button>\n        <button onclick="setStampAddition(22, 20)" class="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">Add +20 (42)</button>\n        <button onclick="setStampAddition(22, 30)" class="px-3 py-1.5 bg-cyan-700 text-white rounded font-mono font-bold">Add +30 (52)</button>\n        <button onclick="setStampAddition(22, 40)" class="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">Add +40 (62)</button>\n    </div>\n</div>\n', 'sim_backward_line_jumps': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-rose-400">Interactive Lab 7</span>\n            <h3 class="text-lg font-bold text-slate-100">Backward Leaps (52 - 37)</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-rose-500/20 text-rose-300 font-semibold border border-rose-500/30">52 - 37 = 15</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Out of <strong>52 stamps</strong>, 37 are portrait stamps. Find the remaining monument stamps by taking strategic backward leaps on an open number line!\n    </p>\n\n    <!-- Number Line Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-4 flex flex-col items-center">\n        <!-- SVG Step Animation -->\n        <div class="w-full overflow-x-auto py-2">\n            <svg id="backJumpSvg" viewBox="0 0 550 100" class="w-full min-w-[480px] h-24">\n                <line x1="30" y1="60" x2="520" y2="60" stroke="#475569" stroke-width="3"/>\n                <!-- Ticks -->\n                <circle cx="500" cy="60" r="5" fill="#f43f5e"/>\n                <text x="500" y="82" fill="#f43f5e" font-size="11" text-anchor="middle" font-family="monospace">52 (Start)</text>\n\n                <!-- Hop 1 (-10) -->\n                <path d="M500,55 Q450,20 400,55" fill="none" stroke="#f43f5e" stroke-width="2"/>\n                <text x="450" y="25" fill="#fda4af" font-size="10" text-anchor="middle">-10</text>\n                <circle cx="400" cy="60" r="4" fill="#cbd5e1"/>\n                <text x="400" y="82" fill="#94a3b8" font-size="11" text-anchor="middle" font-family="monospace">42</text>\n\n                <!-- Hop 2 (-10) -->\n                <path d="M400,55 Q350,20 300,55" fill="none" stroke="#f43f5e" stroke-width="2"/>\n                <text x="350" y="25" fill="#fda4af" font-size="10" text-anchor="middle">-10</text>\n                <circle cx="300" cy="60" r="4" fill="#cbd5e1"/>\n                <text x="300" y="82" fill="#94a3b8" font-size="11" text-anchor="middle" font-family="monospace">32</text>\n\n                <!-- Hop 3 (-10) -->\n                <path d="M300,55 Q250,20 200,55" fill="none" stroke="#f43f5e" stroke-width="2"/>\n                <text x="250" y="25" fill="#fda4af" font-size="10" text-anchor="middle">-10</text>\n                <circle cx="200" cy="60" r="4" fill="#cbd5e1"/>\n                <text x="200" y="82" fill="#94a3b8" font-size="11" text-anchor="middle" font-family="monospace">22</text>\n\n                <!-- Hop 4 (-7: split -2 to 20, -5 to 15) -->\n                <path d="M200,55 Q165,30 130,55" fill="none" stroke="#f59e0b" stroke-width="2"/>\n                <text x="165" y="32" fill="#fde68a" font-size="10" text-anchor="middle">-7</text>\n                <circle cx="130" cy="60" r="6" fill="#10b981"/>\n                <text x="130" y="82" fill="#34d399" font-size="12" font-weight="bold" text-anchor="middle" font-family="monospace">15 (Ans)</text>\n            </svg>\n        </div>\n\n        <div id="backJumpResultTxt" class="mt-2 p-2.5 bg-slate-900 rounded-lg text-xs font-mono text-center text-slate-300 border border-slate-800">\n            52 - 30 = 22, then 22 - 7 = <strong>15 Monument Stamps</strong>!\n        </div>\n    </div>\n\n    <!-- Stepper Buttons -->\n    <div class="flex flex-wrap gap-2 justify-center text-xs">\n        <button onclick="setBackJumpDemo(52, 37)" class="px-3 py-1.5 bg-rose-700 text-white rounded font-mono font-bold">52 - 37 = 15</button>\n        <button onclick="setBackJumpDemo(64, 28)" class="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">64 - 28 = 36</button>\n        <button onclick="setBackJumpDemo(75, 42)" class="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">75 - 42 = 33</button>\n    </div>\n</div>\n', 'sim_target_jump_projections': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-amber-400">Interactive Lab 8</span>\n            <h3 class="text-lg font-bold text-slate-100">Distance to Target (52 + ? = 75)</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-amber-500/20 text-amber-300 font-semibold border border-amber-500/30">Forward Gap = 23</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        You have <strong>52 stamps</strong> and aim for <strong>75 stamps</strong>. Journey forward from 52 to 75 in structured leaps!\n    </p>\n\n    <!-- Target Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-4 text-center">\n        <div class="grid grid-cols-3 gap-2 max-w-sm mx-auto mb-3 text-xs">\n            <div class="bg-slate-900 p-2 rounded-lg border border-slate-800">\n                <span class="text-slate-400 block">Current</span>\n                <span class="text-xl font-bold font-mono text-cyan-300">52</span>\n            </div>\n            <div class="bg-amber-950/40 p-2 rounded-lg border border-amber-600/50 flex flex-col items-center justify-center">\n                <span class="text-[10px] text-amber-300 font-bold block">GAP NEEDED</span>\n                <span id="targetGapDisplay" class="text-2xl font-black font-mono text-amber-400">23</span>\n            </div>\n            <div class="bg-slate-900 p-2 rounded-lg border border-slate-800">\n                <span class="text-slate-400 block">Goal Target</span>\n                <span class="text-xl font-bold font-mono text-emerald-300">75</span>\n            </div>\n        </div>\n\n        <!-- 2-Step Leap Diagram -->\n        <div class="p-3 bg-slate-900 rounded-lg border border-slate-800 text-xs font-mono text-slate-200">\n            <div class="text-amber-300 font-bold text-sm mb-1">Two-Step Journey:</div>\n            <div>Step 1: Jump +20 from 52 ➜ <strong class="text-cyan-300">72</strong></div>\n            <div>Step 2: Jump +3 from 72 ➜ <strong class="text-emerald-300">75</strong></div>\n            <div class="mt-2 text-emerald-400 font-bold">Total Stamps Needed: 20 + 3 = 23 Stamps!</div>\n        </div>\n    </div>\n\n    <!-- Presets -->\n    <div class="flex flex-wrap gap-2 justify-center text-xs">\n        <button onclick="setTargetDemo(52, 75)" class="px-3 py-1.5 bg-amber-600 text-white rounded font-mono font-bold">Target 75 from 52 (23)</button>\n        <button onclick="setTargetDemo(40, 68)" class="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">Target 68 from 40 (28)</button>\n        <button onclick="setTargetDemo(35, 80)" class="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">Target 80 from 35 (45)</button>\n    </div>\n</div>\n', 'sim_decade_hop_jumps': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-green-400">Interactive Lab 9</span>\n            <h3 class="text-lg font-bold text-slate-100">Leaping Garden Creature Hops (+10 / -10)</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-green-500/20 text-green-300 font-semibold border border-green-500/30">Decade Leaps</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Frogs leap forward by <strong>+10</strong> and grasshoppers hop backward by <strong>-10</strong>! Watch how the ones digit stays steady while tens shift smoothly.\n    </p>\n\n    <!-- Leaping Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-4 text-center">\n        <div class="flex justify-between items-center mb-3 text-xs">\n            <span class="text-slate-400">Current Creature Position:</span>\n            <span id="creaturePosBadge" class="text-3xl font-black font-mono text-green-400">34</span>\n            <span class="text-slate-400 font-mono">Ones digit: <strong id="creatureOnesFix" class="text-amber-300">4</strong> (Steady)</span>\n        </div>\n\n        <!-- Visual Jumping Trail -->\n        <div id="creatureJumpTrail" class="min-h-[60px] bg-slate-900 rounded-lg p-2.5 border border-slate-800 flex items-center justify-center gap-2 font-mono text-sm">\n            <!-- Dynamic hop trail -->\n        </div>\n\n        <div id="creatureActionStatus" class="mt-2 text-xs font-semibold text-slate-300">\n            Click Leap Forward (+10) or Hop Backward (-10)!\n        </div>\n    </div>\n\n    <!-- Action Buttons -->\n    <div class="grid grid-cols-2 sm:grid-cols-4 gap-2 pt-1">\n        <button onclick="creatureHop(10)" class="px-3 py-2 bg-green-700 hover:bg-green-600 text-white rounded-lg text-xs font-bold shadow flex items-center justify-center gap-1">\n            <span>🐸 Frog Leap (+10)</span>\n        </button>\n        <button onclick="creatureHop(-10)" class="px-3 py-2 bg-emerald-800 hover:bg-emerald-700 text-white rounded-lg text-xs font-bold shadow flex items-center justify-center gap-1">\n            <span>🦗 Grasshopper (-10)</span>\n        </button>\n        <button onclick="setCreatureStart(24)" class="px-3 py-2 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded-lg text-xs font-mono">\n            Start at 24\n        </button>\n        <button onclick="setCreatureStart(78)" class="px-3 py-2 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded-lg text-xs font-mono">\n            Start at 78\n        </button>\n    </div>\n</div>\n', 'sim_hidden_leaf_puzzles': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-lime-400">Interactive Lab 10</span>\n            <h3 class="text-lg font-bold text-slate-100">Ant Colony Under the Leaf</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-lime-500/20 text-lime-300 font-semibold border border-lime-500/30">Total 50 - Visible 35 = 15</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        A total foraging team of <strong>50 ants</strong> is active. You observe 35 marching outside. How many are hidden under the broad mango leaf?\n    </p>\n\n    <!-- Garden Leaf Scene -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-4">\n        <div class="grid grid-cols-1 md:grid-cols-2 gap-4 items-center">\n            <!-- Open Marching Ants Area -->\n            <div class="bg-slate-900 p-3 rounded-xl border border-slate-800 text-center">\n                <span class="text-xs font-bold text-slate-300 uppercase block mb-1">Visible Marching Ants</span>\n                <span id="antVisibleBadge" class="text-2xl font-black font-mono text-lime-400">35 Ants</span>\n                <div class="text-[11px] text-slate-400 mt-1">Marching in disciplined order along path</div>\n            </div>\n\n            <!-- Broad Mango Leaf -->\n            <div class="bg-emerald-950/40 p-3 rounded-xl border border-emerald-600/40 text-center relative overflow-hidden flex flex-col items-center">\n                <div class="flex justify-between items-center w-full mb-1">\n                    <span class="text-xs font-bold text-emerald-300 uppercase">Under Broad Leaf</span>\n                    <button onclick="toggleLeaf()" id="leafToggleBtn" class="text-[10px] px-2 py-0.5 rounded bg-emerald-700 hover:bg-emerald-600 text-white font-bold">Lift Leaf</button>\n                </div>\n                <!-- Leaf graphic / container -->\n                <div id="leafCoverGraphic" class="w-full h-16 bg-gradient-to-r from-emerald-800 to-green-900 rounded-xl flex items-center justify-center border-2 border-emerald-400/50 shadow-md">\n                    <span class="text-2xl">🍃</span>\n                    <span id="leafStatusTxt" class="text-xs font-bold text-emerald-200 ml-1">Leaf Sheltering Colony</span>\n                </div>\n                <div id="hiddenAntsRevealed" class="hidden mt-2 text-xs font-mono font-bold text-amber-300">\n                    🐜 15 Ants Revealed Resting Here!\n                </div>\n                <span id="leafCountTxt" class="text-xs font-mono text-emerald-300 font-bold mt-2">Hidden: 15 Ants (50 - 35 = 15)</span>\n            </div>\n        </div>\n\n        <div class="mt-3 p-2.5 bg-slate-900 rounded-lg border border-slate-800 text-center text-xs font-mono text-lime-200">\n            Estimation Check: 35 is more than half of 50, so hidden ants must be less than 25 (Exact: 15).\n        </div>\n    </div>\n\n    <!-- Presets -->\n    <div class="flex flex-wrap gap-2 justify-center text-xs">\n        <button onclick="setAntPreset(50, 35)" class="px-3 py-1.5 bg-lime-700 text-white rounded font-mono font-bold">50 Total (35 Vis ➜ 15 Hidden)</button>\n        <button onclick="setAntPreset(40, 24)" class="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">40 Total (24 Vis ➜ 16 Hidden)</button>\n        <button onclick="setAntPreset(60, 42)" class="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">60 Total (42 Vis ➜ 18 Hidden)</button>\n    </div>\n</div>\n', 'sim_hundred_grid_navigation': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-sky-400">Interactive Lab 11</span>\n            <h3 class="text-lg font-bold text-slate-100">100-Grid Arrow Navigator</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-sky-500/20 text-sky-300 font-semibold border border-sky-500/30">Spatial Operations</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Navigate the 1-100 chart! ⬇️ Down adds 10, ⬆️ Up subtracts 10, ➡️ Right adds 1, ⬅️ Left subtracts 1. Tap arrows to journey!\n    </p>\n\n    <!-- 100 Grid Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-3 flex flex-col items-center">\n        <div class="flex justify-between items-center w-full mb-2 text-xs">\n            <span class="text-slate-400">Current Position: <strong id="navGridPos" class="text-sky-400 text-sm font-mono font-bold">45</strong></span>\n            <span id="navArrowHistory" class="text-amber-300 font-mono">Path: Start 45</span>\n        </div>\n\n        <!-- 10x10 Mini Grid -->\n        <div id="navMiniGrid" class="grid grid-cols-10 gap-1 w-full max-w-sm aspect-square bg-slate-900 p-2 rounded-lg border border-slate-800 select-none">\n            <!-- 100 cells dynamically generated -->\n        </div>\n\n        <!-- Directional D-Pad Controls -->\n        <div class="flex flex-col items-center gap-1.5 mt-3">\n            <button onclick="navGridStep(\'up\')" class="w-12 h-9 rounded-lg bg-sky-800 hover:bg-sky-700 font-bold text-white text-xs shadow flex items-center justify-center">⬆️ -10</button>\n            <div class="flex gap-2">\n                <button onclick="navGridStep(\'left\')" class="w-12 h-9 rounded-lg bg-sky-800 hover:bg-sky-700 font-bold text-white text-xs shadow flex items-center justify-center">⬅️ -1</button>\n                <button onclick="navGridReset()" class="px-2 h-9 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-mono text-[11px]">Reset</button>\n                <button onclick="navGridStep(\'right\')" class="w-12 h-9 rounded-lg bg-sky-800 hover:bg-sky-700 font-bold text-white text-xs shadow flex items-center justify-center">➡️ +1</button>\n            </div>\n            <button onclick="navGridStep(\'down\')" class="w-12 h-9 rounded-lg bg-sky-800 hover:bg-sky-700 font-bold text-white text-xs shadow flex items-center justify-center">⬇️ +10</button>\n        </div>\n    </div>\n</div>\n', 'sim_grid_race_game': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-yellow-400">Interactive Lab 12</span>\n            <h3 class="text-lg font-bold text-slate-100">1-to-100 Grid Race Arena</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-yellow-500/20 text-yellow-300 font-semibold border border-yellow-500/30">Target: 91-100</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Roll two dice, combine digits into a 2-digit number (e.g. 3 & 5 ➜ 35 or 53), then choose to Add or Subtract to race toward the 91-100 goal!\n    </p>\n\n    <!-- Race Arena Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-4 text-center">\n        <!-- Status Bar -->\n        <div class="flex justify-between items-center mb-3 text-xs">\n            <span class="text-slate-400">Current Cell: <strong id="racePlayerPos" class="text-yellow-400 font-mono text-base">42</strong></span>\n            <span id="raceStatusBadge" class="text-emerald-400 font-bold font-mono">Racing Forward!</span>\n        </div>\n\n        <!-- Dice Roll Outcome Box -->\n        <div class="bg-slate-900 border border-slate-800 p-3 rounded-xl max-w-sm mx-auto mb-3">\n            <div class="flex items-center justify-center gap-3">\n                <div id="diceA" class="w-10 h-10 rounded-lg bg-amber-600 text-white font-black text-xl flex items-center justify-center shadow">3</div>\n                <div id="diceB" class="w-10 h-10 rounded-lg bg-amber-600 text-white font-black text-xl flex items-center justify-center shadow">5</div>\n            </div>\n            <div class="text-xs text-slate-300 mt-2">\n                Available Moves: <span id="raceMoveChoicesTxt" class="font-mono text-yellow-300 font-bold">35 or 53</span>\n            </div>\n        </div>\n\n        <!-- Action Choice Buttons -->\n        <div class="flex flex-wrap gap-2 justify-center text-xs">\n            <button onclick="applyRaceMove(\'add\', false)" id="btnRaceAddLow" class="px-3 py-1.5 rounded bg-emerald-700 hover:bg-emerald-600 text-white font-bold">Add 35 (+35)</button>\n            <button onclick="applyRaceMove(\'add\', true)" id="btnRaceAddHigh" class="px-3 py-1.5 rounded bg-emerald-800 hover:bg-emerald-700 text-white font-bold">Add 53 (+53)</button>\n            <button onclick="applyRaceMove(\'sub\', false)" id="btnRaceSubLow" class="px-3 py-1.5 rounded bg-rose-800 hover:bg-rose-700 text-white font-bold">Sub 35 (-35)</button>\n        </div>\n    </div>\n\n    <!-- Controls -->\n    <div class="flex justify-between items-center pt-1 text-xs">\n        <button onclick="rollRaceDice()" class="px-4 py-2 bg-yellow-600 hover:bg-yellow-500 text-slate-950 font-bold rounded-lg shadow">\n            🎲 Roll Dice\n        </button>\n        <button onclick="resetRaceGame()" class="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-lg">\n            Reset to Cell 1\n        </button>\n    </div>\n</div>\n', 'sim_magic_square_matrix': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-purple-400">Interactive Lab 13</span>\n            <h3 class="text-lg font-bold text-slate-100">Classic 3×3 Magic Square (Sum = 15)</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-purple-500/20 text-purple-300 font-semibold border border-purple-500/30">Constant Sum 15</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        In this 3×3 grid using digits 1 through 9, every horizontal row, vertical column, and diagonal adds up to <strong>15</strong>!\n    </p>\n\n    <!-- Magic Square Grid -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-4 flex flex-col items-center">\n        <div class="grid grid-cols-3 gap-2 w-48 sm:w-56 aspect-square p-2 bg-slate-900 rounded-xl border border-slate-800 shadow-inner">\n            <!-- Row 1 -->\n            <div class="bg-purple-950/60 border border-purple-500/50 rounded-lg flex items-center justify-center text-xl font-mono font-bold text-purple-200">8</div>\n            <div class="bg-purple-950/60 border border-purple-500/50 rounded-lg flex items-center justify-center text-xl font-mono font-bold text-purple-200">1</div>\n            <div class="bg-purple-950/60 border border-purple-500/50 rounded-lg flex items-center justify-center text-xl font-mono font-bold text-purple-200">6</div>\n            <!-- Row 2 -->\n            <div class="bg-purple-950/60 border border-purple-500/50 rounded-lg flex items-center justify-center text-xl font-mono font-bold text-purple-200">3</div>\n            <div class="bg-amber-600 border-2 border-amber-300 rounded-lg flex items-center justify-center text-2xl font-mono font-black text-slate-950 shadow">5</div>\n            <div class="bg-purple-950/60 border border-purple-500/50 rounded-lg flex items-center justify-center text-xl font-mono font-bold text-purple-200">7</div>\n            <!-- Row 3 -->\n            <div class="bg-purple-950/60 border border-purple-500/50 rounded-lg flex items-center justify-center text-xl font-mono font-bold text-purple-200">4</div>\n            <div class="bg-purple-950/60 border border-purple-500/50 rounded-lg flex items-center justify-center text-xl font-mono font-bold text-purple-200">9</div>\n            <div class="bg-purple-950/60 border border-purple-500/50 rounded-lg flex items-center justify-center text-xl font-mono font-bold text-purple-200">2</div>\n        </div>\n\n        <!-- Verification Line Chooser -->\n        <div class="mt-3 p-2.5 rounded-lg bg-slate-900 border border-slate-800 text-center text-xs font-mono text-purple-300 w-full max-w-sm">\n            <span id="magicSumEquation">Top Row: 8 + 1 + 6 = 15</span>\n        </div>\n    </div>\n\n    <!-- Line Checking Buttons -->\n    <div class="flex flex-wrap gap-1.5 justify-center text-xs">\n        <button onclick="checkMagicLine(\'r1\')" class="px-2.5 py-1 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">Row 1 (8+1+6)</button>\n        <button onclick="checkMagicLine(\'r2\')" class="px-2.5 py-1 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">Row 2 (3+5+7)</button>\n        <button onclick="checkMagicLine(\'r3\')" class="px-2.5 py-1 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">Row 3 (4+9+2)</button>\n        <button onclick="checkMagicLine(\'c1\')" class="px-2.5 py-1 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">Col 1 (8+3+4)</button>\n        <button onclick="checkMagicLine(\'diag\')" class="px-2.5 py-1 bg-purple-800 hover:bg-purple-700 text-white rounded font-mono font-bold">Diag (8+5+2)</button>\n    </div>\n</div>\n', 'sim_radish_harvest_bundles': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-rose-400">Interactive Lab 14</span>\n            <h3 class="text-lg font-bold text-slate-100">Radish Harvest (25 + 36 = 61)</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-rose-500/20 text-rose-300 font-semibold border border-rose-500/30">Regrouping 10 Ones into 1 Ten</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Combine 25 red radishes and 36 white radishes. 5 ones + 6 ones = 11 ones, which regroups into <strong>1 new ten</strong> and 1 loose radish!\n    </p>\n\n    <!-- Harvest Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-4">\n        <div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n            <!-- 25 Red Radishes -->\n            <div class="bg-slate-900 p-3 rounded-xl border border-rose-700/50 flex flex-col items-center">\n                <span class="text-xs font-bold text-rose-300 mb-1">Red Radishes: 25</span>\n                <span class="text-xs text-slate-400 font-mono">2 bundles of 10 + 5 loose</span>\n                <div class="flex gap-2 my-2 items-center">\n                    <div class="w-7 h-10 bg-rose-900 border border-rose-400 rounded flex items-center justify-center text-[10px] text-rose-200 font-bold">10</div>\n                    <div class="w-7 h-10 bg-rose-900 border border-rose-400 rounded flex items-center justify-center text-[10px] text-rose-200 font-bold">10</div>\n                    <span class="text-xs text-slate-400">+ 5 singles</span>\n                </div>\n            </div>\n\n            <!-- 36 White Radishes -->\n            <div class="bg-slate-900 p-3 rounded-xl border border-slate-600/50 flex flex-col items-center">\n                <span class="text-xs font-bold text-slate-200 mb-1">White Radishes: 36</span>\n                <span class="text-xs text-slate-400 font-mono">3 bundles of 10 + 6 loose</span>\n                <div class="flex gap-2 my-2 items-center">\n                    <div class="w-7 h-10 bg-slate-800 border border-slate-400 rounded flex items-center justify-center text-[10px] text-slate-200 font-bold">10</div>\n                    <div class="w-7 h-10 bg-slate-800 border border-slate-400 rounded flex items-center justify-center text-[10px] text-slate-200 font-bold">10</div>\n                    <div class="w-7 h-10 bg-slate-800 border border-slate-400 rounded flex items-center justify-center text-[10px] text-slate-200 font-bold">10</div>\n                    <span class="text-xs text-slate-400">+ 6 singles</span>\n                </div>\n            </div>\n        </div>\n\n        <!-- Combined Total with Regrouping -->\n        <div class="mt-3 p-3 bg-slate-900 rounded-lg border border-slate-800 text-center font-mono">\n            <div class="text-xs text-slate-400">Step 1: Tens = 20 + 30 = 50. Step 2: Ones = 5 + 6 = 11 (10 + 1).</div>\n            <div class="text-xl font-black text-rose-300 mt-1">Total: 50 + 11 = 61 Radishes</div>\n            <div class="text-xs text-emerald-400 mt-1">Result: 6 bundles of 10 + 1 single radish = 61!</div>\n        </div>\n    </div>\n</div>\n', 'sim_vegetable_crate_complements': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-orange-400">Interactive Lab 15</span>\n            <h3 class="text-lg font-bold text-slate-100">100-Capacity Storage Crate (65 + ? = 100)</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-orange-500/20 text-orange-300 font-semibold border border-orange-500/30">Target 100 Complement</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        A vegetable crate holds 100 items. Adjust the tomato count to see how many carrots are needed to fill the crate completely to 100!\n    </p>\n\n    <!-- Crate Visual -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-4 text-center">\n        <!-- 10x10 Grid representation -->\n        <div class="flex justify-between items-center mb-2 text-xs">\n            <span class="text-rose-400 font-bold">🍅 Tomatoes: <span id="crateTomatoesVal">65</span></span>\n            <span class="text-orange-400 font-bold">🥕 Carrots: <span id="crateCarrotsVal">35</span></span>\n            <span class="text-amber-300 font-mono font-bold">Total: 100</span>\n        </div>\n\n        <!-- 10-bar multi visual -->\n        <div class="w-full h-8 bg-slate-900 rounded-lg border border-slate-800 flex overflow-hidden my-2">\n            <div id="crateTomatoesBar" style="width: 65%;" class="bg-rose-600 flex items-center justify-center text-xs font-bold font-mono text-white transition-all duration-300">\n                65 Tomatoes\n            </div>\n            <div id="crateCarrotsBar" style="width: 35%;" class="bg-orange-500 flex items-center justify-center text-xs font-bold font-mono text-slate-950 transition-all duration-300">\n                35 Carrots\n            </div>\n        </div>\n\n        <div id="crateComplementEquation" class="p-2.5 bg-slate-900 rounded-lg border border-slate-800 text-xs font-mono text-amber-200 mt-2">\n            Complement: 100 - 65 = <strong>35 Carrots</strong> (65 + 35 = 100)\n        </div>\n    </div>\n\n    <!-- Presets -->\n    <div class="flex flex-wrap gap-2 justify-center text-xs">\n        <button onclick="setCrateTomatoes(65)" class="px-3 py-1.5 bg-orange-700 text-white rounded font-mono font-bold">65 Tomatoes ➜ 35 Carrots</button>\n        <button onclick="setCrateTomatoes(40)" class="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">40 Tomatoes ➜ 60 Carrots</button>\n        <button onclick="setCrateTomatoes(75)" class="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">75 Tomatoes ➜ 25 Carrots</button>\n        <button onclick="setCrateTomatoes(82)" class="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded font-mono">82 Tomatoes ➜ 18 Carrots</button>\n    </div>\n</div>\n', 'sim_apple_harvest_comparison': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-red-400">Interactive Lab 16</span>\n            <h3 class="text-lg font-bold text-slate-100">Apple Harvest Comparison (85 vs 67)</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-red-500/20 text-red-300 font-semibold border border-red-500/30">Total 152 | Difference 18</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Basket A holds <strong>85 apples</strong> and Basket B holds <strong>67 apples</strong>. Explore the combined total sum and the exact comparative difference margin!\n    </p>\n\n    <!-- Comparison Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-4 text-center">\n        <div class="grid grid-cols-2 gap-3 max-w-sm mx-auto mb-3">\n            <div class="bg-red-950/50 border border-red-600/50 p-3 rounded-xl flex flex-col items-center">\n                <span class="text-xs font-bold text-red-300">Basket A</span>\n                <span class="text-3xl font-black font-mono text-white my-1">85</span>\n                <span class="text-[10px] text-slate-400">Apples</span>\n            </div>\n            <div class="bg-amber-950/50 border border-amber-600/50 p-3 rounded-xl flex flex-col items-center">\n                <span class="text-xs font-bold text-amber-300">Basket B</span>\n                <span class="text-3xl font-black font-mono text-white my-1">67</span>\n                <span class="text-[10px] text-slate-400">Apples</span>\n            </div>\n        </div>\n\n        <!-- Comparative Output Box -->\n        <div id="appleComparisonDisplay" class="p-3 bg-slate-900 rounded-lg border border-slate-800 text-xs font-mono space-y-1">\n            <div class="text-emerald-400 font-bold text-sm">Combined Total: 85 + 67 = 152 Apples</div>\n            <div class="text-amber-300 font-bold">Difference Margin: 85 - 67 = 18 More Apples in Basket A!</div>\n        </div>\n    </div>\n\n    <!-- Toggle Buttons -->\n    <div class="flex justify-center gap-2 text-xs">\n        <button onclick="setAppleMode(\'total\')" class="px-3 py-1.5 bg-emerald-700 hover:bg-emerald-600 text-white rounded font-bold">View Addition Total (152)</button>\n        <button onclick="setAppleMode(\'diff\')" class="px-3 py-1.5 bg-amber-700 hover:bg-amber-600 text-white rounded font-bold">View Difference (18)</button>\n    </div>\n</div>\n'}
